        // Calcula impuesto del 16% sobre el precio con descuento
        // Calcula total e imprime todo formateado

    }
}

solution:
public class CalculadoraImpuestos {
    public static void main(String[] args) {
        final double PRECIO_UNITARIO = 49.99;
        final double IMPUESTO = 0.16;
        int cantidad = 12;

        double subtotal = PRECIO_UNITARIO * cantidad;

        // Descuento condicional con ternario anidado
        double porcentajeDescuento = cantidad > 10 ? 0.15
            : cantidad > 5 ? 0.10
            : 0.0;

        double montoDescuento = subtotal * porcentajeDescuento;
        double precioConDescuento = subtotal - montoDescuento;
        double impuestoMonto = precioConDescuento * IMPUESTO;
        double total = precioConDescuento + impuestoMonto;

        System.out.printf("Precio unitario: $%.2f%n", PRECIO_UNITARIO);
        System.out.printf("Cantidad: %d%n", cantidad);
        System.out.printf("Subtotal: $%.2f%n", subtotal);
        System.out.printf("Descuento (%.0f%%): -$%.2f%n",
            porcentajeDescuento * 100, montoDescuento);
        System.out.printf("Precio con descuento: $%.2f%n", precioConDescuento);
        System.out.printf("Impuesto (16%%): $%.2f%n", impuestoMonto);
        System.out.printf("Total: $%.2f%n", total);
    }
}
